async function liberarOnboardingEmMassa(alunoIds) {
  const db2 = await getDb();
  if (!db2) return { success: false, message: "Erro de conex\xE3o com banco", liberados: 0, erros: [] };
  if (alunoIds.length === 0) {
    return { success: false, message: "Nenhum aluno selecionado", liberados: 0, erros: [] };
  }
  const alunosEncontrados = await db2.select({ id: alunos.id, name: alunos.name, onboardingLiberado: alunos.onboardingLiberado }).from(alunos).where(inArray(alunos.id, alunoIds));
  const alunosComPdi = await db2.select({ alunoId: assessmentPdi.alunoId }).from(assessmentPdi).where(inArray(assessmentPdi.alunoId, alunoIds)).groupBy(assessmentPdi.alunoId);
  const alunoIdsComPdi = new Set(alunosComPdi.map((a) => a.alunoId));
  const erros = [];
  const idsParaLiberar = [];
  for (const id of alunoIds) {
    const aluno = alunosEncontrados.find((a) => a.id === id);
    if (!aluno) {
      erros.push(`Aluno ID ${id}: n\xE3o encontrado`);
      continue;
    }
    if (!alunoIdsComPdi.has(id)) {
      erros.push(`${aluno.name}: sem PDI (j\xE1 deve ir para onboarding automaticamente)`);
      continue;
    }
    if (aluno.onboardingLiberado === 1) {
      erros.push(`${aluno.name}: onboarding j\xE1 liberado`);
      continue;
    }
    idsParaLiberar.push(id);
  }
  if (idsParaLiberar.length > 0) {
    for (const id of idsParaLiberar) {
      try {
        await arquivarCicloAtual(id);
      } catch (e) {
        console.warn(`[DB] Erro ao arquivar ciclo do aluno ${id}:`, e);
      }
    }
    await db2.update(alunos).set({
      onboardingLiberado: 1,
      onboardingLiberadoEm: /* @__PURE__ */ new Date()
    }).where(inArray(alunos.id, idsParaLiberar));
  }
  return {
    success: true,
    message: `Onboarding liberado para ${idsParaLiberar.length} aluno(s)${erros.length > 0 ? `. ${erros.length} ignorado(s).` : "."}`,
    liberados: idsParaLiberar.length,
    erros
  };
}
