async function avaliarElegibilidadeCertificacao(alunoId, contratoNivelId) {
  const nivel = await getContratoNivelComStatusOperacional(alunoId, contratoNivelId);
  if (!nivel) {
    return { elegivel: false, motivo: "N\xEDvel n\xE3o encontrado." };
  }
  const pedagogia = await getPedagogiaByNivel(alunoId, contratoNivelId);
  const assessments = pedagogia.assessments || [];
  const metasNivel = pedagogia.metas || [];
  const eventos = pedagogia.eventParticipation || [];
  const cases = pedagogia.casesSucesso || [];
  const nivelEncerrado = nivel.statusOperacional === "encerrado";
  const resultadoFinalFechado = assessments.some((a) => ["finalizado", "concluido"].includes(String(a.status)));
  const engajamento = eventos.length > 0 ? eventos.filter((e) => e.status === "presente").length / eventos.length * 100 : 0;
  const desafios = metasNivel.length > 0 ? metasNivel.filter((m) => String(m.status || "").toLowerCase() === "concluida").length / metasNivel.length * 100 : 0;
  const evidencias = cases.filter((c) => c.entregue === 1).length;
  const criterios = {
    nivelEncerrado,
    resultadoFinalFechado,
    engajamentoMin80: engajamento >= 80,
    desafiosMin80: desafios >= 80,
    evidenciasMinimas: evidencias > 0
  };
  const elegivel = criterios.nivelEncerrado && criterios.resultadoFinalFechado && criterios.engajamentoMin80 && criterios.desafiosMin80 && criterios.evidenciasMinimas;
  const motivos = [];
  if (!criterios.nivelEncerrado) motivos.push("N\xEDvel n\xE3o est\xE1 encerrado.");
  if (!criterios.resultadoFinalFechado) motivos.push("Resultado final do n\xEDvel n\xE3o est\xE1 fechado.");
  if (!criterios.engajamentoMin80) motivos.push("Engajamento final abaixo de 80%.");
  if (!criterios.desafiosMin80) motivos.push("Desafios conclu\xEDdos abaixo de 80%.");
  if (!criterios.evidenciasMinimas) motivos.push("Sem evid\xEAncias/cases entregues no n\xEDvel.");
  return {
    elegivel,
    criterios,
    metricas: {
      engajamento: Number(engajamento.toFixed(2)),
      desafios: Number(desafios.toFixed(2)),
      evidencias
    },
    motivo: motivos.join(" "),
    nivel
  };
}
async function syncStudentPerformanceFromPlatform(alunoId, cursoAtribuidoId) {
  const db2 = await getDb();
  if (!db2) return;
  try {
    const [cursoAtrib] = await db2.select().from(alunoCursoAtribuido).where(
      and(
        eq(alunoCursoAtribuido.id, cursoAtribuidoId),
        eq(alunoCursoAtribuido.alunoId, alunoId)
      )
    ).limit(1);
    if (!cursoAtrib) return;
    const { cursoId, competenciaId } = cursoAtrib;
    const [alunoData] = await db2.select({ externalId: alunos.externalId, name: alunos.name, email: alunos.email }).from(alunos).where(eq(alunos.id, alunoId)).limit(1);
    if (!alunoData) return;
    const externalUserId = alunoData.externalId || String(alunoId);
    const [compData] = await db2.select({ codigoIntegracao: competencias.codigoIntegracao, nome: competencias.nome }).from(competencias).where(eq(competencias.id, competenciaId)).limit(1);
    const externalCompetenciaId = compData?.codigoIntegracao || String(competenciaId);
    const competenciaName = compData?.nome || "";
    const todasAtividades = await db2.select({ id: atividadesCurso.id }).from(atividadesCurso).where(and(eq(atividadesCurso.cursoId, cursoId), eq(atividadesCurso.isActive, 1)));
    const aulasDisponiveis = todasAtividades.length;
    const atividadesAprovadas = await db2.select({ notaFinal: alunoAtividadeProgresso.notaFinal }).from(alunoAtividadeProgresso).where(
      and(
        eq(alunoAtividadeProgresso.alunoId, alunoId),
        eq(alunoAtividadeProgresso.cursoAtribuidoId, cursoAtribuidoId),
        eq(alunoAtividadeProgresso.status, "aprovada")
      )
    );
    const aulasConcluidas = atividadesAprovadas.length;
    let mediaAvaliacoesRespondidas = null;
    const atividadesComNota = atividadesAprovadas.filter(
      (n) => n.notaFinal !== null && n.notaFinal !== void 0
    );
    if (atividadesComNota.length > 0) {
      const somaNotas = atividadesComNota.reduce(
        (acc, n) => acc + parseFloat(String(n.notaFinal)),
        0
      );
      const media010 = somaNotas / atividadesComNota.length;
      mediaAvaliacoesRespondidas = (media010 * 10).toFixed(2);
    }
    const progressoTotal = aulasDisponiveis > 0 ? Math.round(aulasConcluidas / aulasDisponiveis * 100) : 0;
    const dataConclusaoStr = aulasConcluidas >= aulasDisponiveis && aulasDisponiveis > 0 ? (/* @__PURE__ */ new Date()).toISOString().split("T")[0] : null;
    const existing = await db2.select({ id: studentPerformance.id }).from(studentPerformance).where(
      and(
        eq(studentPerformance.alunoId, alunoId),
        eq(studentPerformance.competenciaId, competenciaId)
      )
    ).limit(1);
    if (existing.length > 0) {
      await db2.update(studentPerformance).set({
        externalUserId,
        aulasConcluidas,
        aulasDisponiveis,
        totalAulas: aulasDisponiveis,
        progressoTotal,
        avaliacoesRespondidas: atividadesComNota.length,
        mediaAvaliacoesRespondidas,
        dataConclusao: dataConclusaoStr,
        updatedAt: /* @__PURE__ */ new Date()
      }).where(eq(studentPerformance.id, existing[0].id));
    } else {
      await db2.insert(studentPerformance).values({
        alunoId,
        externalUserId,
        userName: alunoData.name || "",
        userEmail: alunoData.email || null,
        competenciaId,
        externalCompetenciaId,
        competenciaName,
        aulasConcluidas,
        aulasDisponiveis,
        totalAulas: aulasDisponiveis,
        progressoTotal,
        avaliacoesRespondidas: atividadesComNota.length,
        mediaAvaliacoesRespondidas,
        dataConclusao: dataConclusaoStr
      });
    }
  } catch (error) {
    console.error("[syncStudentPerformanceFromPlatform] Error:", error);
  }
}
