  const media = (scores.D + scores.I + scores.S + scores.C) / 4;
  const variancia = (Math.pow(scores.D - media, 2) + Math.pow(scores.I - media, 2) + Math.pow(scores.S - media, 2) + Math.pow(scores.C - media, 2)) / 4;
