import nodemailer from "nodemailer";
function getTransporter() {
  if (!transporter) {
    if (!ENV.smtpUser || !ENV.smtpPass) {
      throw new Error("SMTP_USER e SMTP_PASS n\xE3o configurados. Configure as credenciais do Gmail.");
    }
    transporter = nodemailer.createTransport({
      host: "smtp.gmail.com",
      port: 587,
      secure: false,
      // STARTTLS
      auth: {
        user: ENV.smtpUser,
        pass: ENV.smtpPass
      }
    });
  }
  return transporter;
}
async function sendEmail(options) {
  const smtpConfigurado = !!(ENV.smtpUser && ENV.smtpPass);
  if (!ENV.emailEnabled && !smtpConfigurado) {
    console.log(`[Email] Envio desativado: EMAIL_ENABLED=false e sem credenciais SMTP. Destinat\xE1rio: ${options.to}`);
    return { success: false, error: "Envio de e-mails temporariamente desativado." };
  }
  if (!ENV.emailEnabled && smtpConfigurado) {
    console.log(`[Email] EMAIL_ENABLED=false ignorado pois SMTP est\xE1 configurado. Prosseguindo envio para: ${options.to}`);
  }
  try {
    const transport = getTransporter();
    const info = await transport.sendMail({
      from: `"ECOSSISTEMA DO BEM" <${ENV.smtpUser}>`,
      to: options.to,
      cc: options.cc || void 0,
      subject: options.subject,
      html: options.html,
      text: options.text || ""
    });
    console.log(`[Email] Enviado para ${options.to}${options.cc ? ` (cc: ${options.cc})` : ""} - MessageID: ${info.messageId}`);
    return { success: true, messageId: info.messageId };
  } catch (error) {
    console.error(`[Email] Erro ao enviar para ${options.to}:`, error.message);
    return { success: false, error: error.message };
  }
}
async function verifySmtpConnection() {
  if (!ENV.emailEnabled) {
    console.log("[Email] Verifica\xE7\xE3o SMTP ignorada: envio desativado.");
    return false;
  }
  try {
    const transport = getTransporter();
    await transport.verify();
    console.log("[Email] Conex\xE3o SMTP verificada com sucesso.");
    return true;
  } catch (error) {
    console.error("[Email] Falha na verifica\xE7\xE3o SMTP:", error.message);
    return false;
  }
}
