  const dataFormatada = (() => {
    const d = /* @__PURE__ */ new Date(data.dataCongelamento + "T12:00:00");
    return d.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" });
  })();
  const isCongelado = data.acao === "congelado";
