    const [trilha] = await db2.select().from(trilhas).where(eq3(trilhas.id, comp.trilhaId));
    const fichasComp = await db2.select().from(fichasPedagogicasCompetencias).where(eq3(fichasPedagogicasCompetencias.competenciaId, input.competenciaId));
    const modulos = await db2.select().from(competenciasModulos).where(eq3(competenciasModulos.competenciaId, input.competenciaId)).orderBy(competenciasModulos.ordem);
    const fichasConts = await db2.select().from(fichasPedagogicasConteudos).where(eq3(fichasPedagogicasConteudos.competenciaId, input.competenciaId));
    const fichasConteudoMap = new Map(fichasConts.map((f) => [f.conteudoId, f]));
